function s(t,r,e){const n=Math.max(0,Number(r)),o=Number(e);return!Number.isFinite(n)||!Number.isFinite(o)||o<=n?null:`${String(t).split("#")[0]}#t=${a(n)},${a(o)}`}function a(t){return String(Number(t.toFixed(3)))}function c(t){return null}function l(t,r){return!t||!r?t!==r:t.sourceId!==r.sourceId||t.start!==r.start}function m(t,r){return`${i(t)} – ${i(r)} (${(r-t).toFixed(1)}s)`}function i(t){const r=Math.max(0,Math.floor(Number(t)||0)),e=String(r%60).padStart(2,"0"),n=Math.floor(r/60)%60,o=Math.floor(r/3600);return o>0?`${o}:${String(n).padStart(2,"0")}:${e}`:`${n}:${e}`}export{s as a,m as c,c as p,l as s};
